import json

with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def build_map(data):
    m = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        m.setdefault(name, {})
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                m[name][(pkg['id'], fw['framework'])] = pkg['resolvedVersion']
    return m

bm = build_map(baseline)
am = build_map(after)

changes = []
unchanged = []
for proj in sorted(set(list(bm.keys()) + list(am.keys()))):
    all_keys = sorted(set(list(bm.get(proj,{}).keys()) + list(am.get(proj,{}).keys())))
    for key in all_keys:
        pkg_id, fw = key
        bv = bm.get(proj, {}).get(key)
        av = am.get(proj, {}).get(key)
        if bv and av and bv != av:
            changes.append((proj, pkg_id, fw, bv, av, 'Aligned to highest version'))
        elif bv and av and bv == av:
            unchanged.append((proj, pkg_id, fw, av))
        elif bv and not av:
            changes.append((proj, pkg_id, fw, bv, 'REMOVED', 'Unexpected removal'))
        elif not bv and av:
            changes.append((proj, pkg_id, fw, 'NONE', av, 'Unexpected addition'))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'  {c[0]:15s} {c[1]:45s} {c[2]:8s} {c[3]:10s} -> {c[4]:10s}  ({c[5]})')
else:
    print('  No changes.')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'  {u[0]:15s} {u[1]:45s} {u[2]:8s} {u[3]}')
"

